mapper.select:
SELECT P.PRJ_NAME
FROM project P
WHERE P.ID = #{prjId}

SELECT COUNT(*)
FROM GRP G
WHERE G.ID = #{grpId}
  AND G.PRJ_ID = #{prjId}
  AND G.STATUS_CD = '01ACTIVE'

SELECT COUNT(*)
FROM MEMBER M
WHERE M.USER_ID = #{userId}
  AND M.GRP_ID = #{grpId}
  AND M.PRJ_END_DATE IS NULL

SELECT TO_CHAR(U.HIRE_DATE, 'YYYY-MM-DD')
FROM USERS U
WHERE U.ID = #{userId}

mapper.delete:
DELETE FROM MEMBER M
WHERE EXISTS (
  SELECT 1 FROM GRP G WHERE G.ID = M.GRP_ID AND G.PRJ_ID = #{prjId}
)
AND (

    (M.USER_ID = #{r.userId} AND M.GRP_ID = #{r.grpId})

)
